import parso

code = """
def function1():
    pass

class MyClass:
    def method1(self):
        pass
"""

module = parso.parse(code)
print("Module children:")
for child in module.children:
    print(f"  Type: {child.type}, Content: {repr(child.get_code())}")

print("\nExploring class children:")
for child in module.children:
