        print(f"Class {child.name.value} children:")
        for c in child.children:
            print(f"  Type: {c.type}, Content: {repr(c.get_code())}")
            if c.type == 'suite':
                print(f"  Suite children:")
                for cc in c.children:
                    print(f"    Type: {cc.type}, Content: {repr(cc.get_code())}")
EOF
